   858      protected:
   859      template<typename T>
   860      bool get_points (hb_font_t *font, hb_codepoint_t gid, T consumer) const
   861      {
   862        /* Making this alloc free is not that easy
   863           https://github.com/harfbuzz/harfbuzz/issues/2095
   864           mostly because of gvar handling in VF fonts,
   865           perhaps a separate path for non-VF fonts can be considered */
   866        contour_point_vector_t all_points;
   867
   868        bool phantom_only = !consumer.is_consuming_contour_points ();
   869        if (unlikely (!glyph_for_gid (gid).get_points ([this] (hb_codepoint_t gid) -> const Glyph { return this->glyph_for_gid (gid); },
   870                                                       font, all_points, phantom_only)))
   871          return false;
   872
   873        if (consumer.is_consuming_contour_points ())
   874        {
   875          for (unsigned point_index = 0; point_index + 4 < all_points.length; ++point_index)
   876            consumer.consume_point (all_points[point_index]);
   877          consumer.points_end ();
   878        }
   879
   880        /* Where to write phantoms, nullptr if not requested */
   881        contour_point_t *phantoms = consumer.get_phantoms_sink ();
   882        if (phantoms)
   883          for (unsigned i = 0; i < PHANTOM_COUNT; ++i)
   884            phantoms[i] = all_points[all_points.length - PHANTOM_COUNT + i];
   885
   886        return true;
   887      }
