   889      public:
   890  #ifndef HB_NO_VAR
   891      struct points_aggregator_t
   892      {
   893        hb_font_t *font;
   894        hb_glyph_extents_t *extents;
   895        contour_point_t *phantoms;
   896
   897        struct contour_bounds_t
   898        {
   899          contour_bounds_t () { min_x = min_y = FLT_MAX; max_x = max_y = -FLT_MAX; }
   900
   901          void add (const contour_point_t &p)
   902          {
   903            min_x = hb_min (min_x, p.x);
   904            min_y = hb_min (min_y, p.y);
   905            max_x = hb_max (max_x, p.x);
   906            max_y = hb_max (max_y, p.y);
   907          }
   908
   909          bool empty () const { return (min_x >= max_x) || (min_y >= max_y); }
   910
   911          void get_extents (hb_font_t *font, hb_glyph_extents_t *extents)
   912          {
   913            if (unlikely (empty ()))
   914            {
   915              extents->width = 0;
   916              extents->x_bearing = 0;
   917              extents->height = 0;
   918              extents->y_bearing = 0;
   919              return;
   920            }
   921            extents->x_bearing = font->em_scalef_x (min_x);
   922            extents->width = font->em_scalef_x (max_x - min_x);
   923            extents->y_bearing = font->em_scalef_y (max_y);
   924            extents->height = font->em_scalef_y (min_y - max_y);
   925          }
   926
   927          protected:
   928          float min_x, min_y, max_x, max_y;
   929        } bounds;
   930
   931        points_aggregator_t (hb_font_t *font_, hb_glyph_extents_t *extents_, contour_point_t *phantoms_)
   932        {
   933          font = font_;
   934          extents = extents_;
   935          phantoms = phantoms_;
   936          if (extents) bounds = contour_bounds_t ();
   937        }
   938
   939        void consume_point (const contour_point_t &point) { bounds.add (point); }
   940        void points_end () { bounds.get_extents (font, extents); }
   941
   942        bool is_consuming_contour_points () { return extents; }
   943        contour_point_t *get_phantoms_sink () { return phantoms; }
   944      };
