   946      unsigned int
   947      get_advance_var (hb_font_t *font, hb_codepoint_t gid, bool is_vertical) const
   948      {
   949        bool success = false;
   950
   951        contour_point_t phantoms[PHANTOM_COUNT];
   952        if (likely (font->num_coords == face->table.gvar->get_axis_count ()))
   953          success = get_points (font, gid, points_aggregator_t (font, nullptr, phantoms));
   954
   955        if (unlikely (!success))
   956          return is_vertical
   957               ? face->table.vmtx->get_advance (gid)
   958               : face->table.hmtx->get_advance (gid);
   959
   960        return is_vertical
   961             ? roundf (phantoms[PHANTOM_TOP].y - phantoms[PHANTOM_BOTTOM].y)
   962             : roundf (phantoms[PHANTOM_RIGHT].x - phantoms[PHANTOM_LEFT].x);
   963      }
   964
   965      int get_side_bearing_var (hb_font_t *font, hb_codepoint_t gid, bool is_vertical) const
   966      {
   967        hb_glyph_extents_t extents;
   968
   969        contour_point_t phantoms[PHANTOM_COUNT];
   970        if (unlikely (!get_points (font, gid, points_aggregator_t (font, &extents, phantoms))))
   971          return is_vertical
   972               ? face->table.vmtx->get_side_bearing (gid)
   973               : face->table.hmtx->get_side_bearing (gid);
   974
   975        return is_vertical
   976             ? ceil (phantoms[PHANTOM_TOP].y) - extents.y_bearing
   977             : floor (phantoms[PHANTOM_LEFT].x);
   978      }
   979  #endif
