   981      bool get_extents (hb_font_t *font, hb_codepoint_t gid, hb_glyph_extents_t *extents) const
   982      {
   983        if (unlikely (gid >= num_glyphs)) return false;
   984  #ifndef HB_NO_VAR
   985        if (font->num_coords && font->num_coords == face->table.gvar->get_axis_count ())
   986          return get_points (font, gid, points_aggregator_t (font, extents, nullptr));
   987  #endif
   988        return glyph_for_gid (gid).get_extents (font, extents);
   989      }
