   991      const Glyph
   992      glyph_for_gid (hb_codepoint_t gid, bool needs_padding_removal = false) const
   993      {
   994        unsigned int start_offset, end_offset;
   995        if (unlikely (gid >= num_glyphs)) return Glyph ();
   996
   997        if (short_offset)
   998        {
   999          const HBUINT16 *offsets = (const HBUINT16 *) loca_table->dataZ.arrayZ;
  1000          start_offset = 2 * offsets[gid];
